// En JavaScript:
document.getElementById('rutScanner').addEventListener('change', function(e) {
    const datosEscaneados = e.target.value;
    
    // Extraer RUT de los datos escaneados
    // Formato típico de cédula chilena: RUN:12345678-9
    const rutMatch = datosEscaneados.match(/RUN:([0-9]+-[0-9kK])/);
    if (rutMatch && rutMatch[1]) {
        const rut = formatearRut(rutMatch[1]);
        document.getElementById('rut').value = rut;
        
        // Automáticamente buscar cliente por RUT
        buscarClientePorRut(rut);
    }
});

function formatearRut(rutSinFormato) {
    // Convertir 12345678-9 a 12.345.678-9
    return rutSinFormato.replace(/^(d{1,2})(d{3})(d{3})([-][0-9kK])$/,
                             '$1.$2.$3$4');
}`})})]}),e.jsx(hs,{}),e.jsxs("div",{className:"space-y-4",children:[e.jsx("h3",{className:"text-lg font-semibold",children:"Características de Seguridad"}),e.jsxs("div",{className:"space-y-2",children:[e.jsx("h4",{className:"font-medium",children:"Validación de Datos"}),e.jsx("p",{className:"text-muted-foreground",children:"El SDK incluye funciones de validación que puede ampliar para sus necesidades específicas:"}),e.jsx("div",{className:"bg-gray-50 p-4 rounded-md",children:e.jsx("pre",{className:"text-sm overflow-auto",children:`// Extender el SDK para agregar validaciones personalizadas
